INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4795032, 687200, 60047, '<td valign="top">I like the use of the black BG. Great DOF. Interesting choice of directional lighting.</td>', 'I like the use of the black BG. Great DOF. Interesting choice of directional lighting.', '2008-07-01 15:58:16.000000', NULL, 1),
(4795036, 690588, 60047, '<td valign="top">Great portrait.</td>', 'Great portrait.', '2008-07-01 15:58:56.000000', NULL, 1),
(4795044, 693721, 60047, '<td valign="top">I realize this is a night shot - and I love the deep blues and rust colors - wonderfully complimentary - I wish it were a tad brighter, though.</td>', 'I realize this is a night shot - and I love the deep blues and rust colors - wonderfully complimentary - I wish it were a tad brighter, though.', '2008-07-01 16:01:32.000000', NULL, 1),
(4795046, 693270, 71558, '<td valign="top">Nice colors and good composition on this shot.</td>', 'Nice colors and good composition on this shot.', '2008-07-01 16:02:22.000000', NULL, 1),
(4795094, 690264, 60047, '<td valign="top">Wow - quite vivid! What a magical place.</td>', 'Wow - quite vivid! What a magical place.', '2008-07-01 16:23:09.000000', NULL, 1),
(4795099, 686173, 60047, '<td valign="top">I really like the shadow covering half his face. The white light thing behind him is a bit distracting - I think the photo would be even more powerful without it.</td>', 'I really like the shadow covering half his face. The white light thing behind him is a bit distracting - I think the photo would be even more powerful without it.', '2008-07-01 16:24:48.000000', NULL, 1),
(4795103, 692145, 60047, '<td valign="top">Great shot. Love the colors.</td>', 'Great shot. Love the colors.', '2008-07-01 16:25:51.000000', NULL, 1),
(4795145, 693444, 811, '<td valign="top">The composition feels a bit centered/static to me.  That orange shirt really grabs attention though, and that dog is HUGE!</td>', 'The composition feels a bit centered/static to me.  That orange shirt really grabs attention though, and that dog is HUGE!', '2008-07-01 16:38:15.000000', NULL, 1),
(4795149, 693591, 811, '<td valign="top">I like the use of negative space in this, but the focus seems just a shade off.</td>', 'I like the use of negative space in this, but the focus seems just a shade off.', '2008-07-01 16:38:36.000000', NULL, 1),
(4795151, 692802, 2134, '<td valign="top">What a great POV... 7</td>', 'What a great POV... 7', '2008-07-01 16:39:05.000000', NULL, 1),
(4795153, 693585, 811, '<td valign="top">Simply gorgeous.  The car adn the picture.  I like the black on black, and its headlights looks like it is giving a menacing stare  Sleek and sophisticated.</td>', 'Simply gorgeous.  The car adn the picture.  I like the black on black, and its headlights looks like it is giving a menacing stare  Sleek and sophisticated.', '2008-07-01 16:39:09.000000', NULL, 1),
(4795158, 693690, 811, '<td valign="top">I like the general composition (though a bit more of its ear would be nice), but the focus seems a bit off, in general.  It''s eyes seem focused, which is good, but the tip of its nose is a "stronger" point, and it seems as if the eyes go there.  Since, the nose is not focused, it feels as if the shot is not focused.</td>', 'I like the general composition (though a bit more of its ear would be nice), but the focus seems a bit off, in general.  It''s eyes seem focused, which is good, but the tip of its nose is a "stronger" point, and it seems as if the eyes go there.  Since, the nose is not focused, it feels as if the shot is not focused.', '2008-07-01 16:40:55.000000', NULL, 1),
(4795160, 686372, 811, '<td valign="top">Great use of negative space and high contrast.  Having the boat a little further down and more to the right would (away from the center line) would have made the composition stronger, I think.</td>', 'Great use of negative space and high contrast.  Having the boat a little further down and more to the right would (away from the center line) would have made the composition stronger, I think.', '2008-07-01 16:41:47.000000', NULL, 1),
(4795161, 686833, 811, '<td valign="top">Cool grab.  Seems a bit soft, though.</td>', 'Cool grab.  Seems a bit soft, though.', '2008-07-01 16:42:06.000000', NULL, 1),
(4795164, 686419, 811, '<td valign="top">Good composition and focus.  It might be just a hair oversharpened, though.</td>', 'Good composition and focus.  It might be just a hair oversharpened, though.', '2008-07-01 16:42:37.000000', NULL, 1),
(4795166, 693803, 811, '<td valign="top">The orange on the flowers is good, and the butterfly is captured well.  I think more color contrast (it seems to orangey) would make it more engaging.</td>', 'The orange on the flowers is good, and the butterfly is captured well.  I think more color contrast (it seems to orangey) would make it more engaging.', '2008-07-01 16:43:17.000000', NULL, 1),
